/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */
import type { RowData } from "@tanstack/react-table"
import React from "react"

import {
  TableColumnGroupOptions,
  TableColumnGroupMenu,
} from "../filters/table-column-group"
import { useColumnHeaderContext } from "./data-table-column-header"

/**
 * Grouping options for column header menu using context.
 */
export function DataTableColumnGroupOptions<TData extends RowData, TValue>(
  props: Omit<React.ComponentProps<typeof TableColumnGroupOptions>, "column">,
) {
  const { column } = useColumnHeaderContext<TData, TValue>(true)
  return <TableColumnGroupOptions column={column} {...props} />
}

DataTableColumnGroupOptions.displayName = "DataTableColumnGroupOptions"

/**
 * Standalone grouping menu for column header using context.
 */
export function DataTableColumnGroupMenu<TData extends RowData, TValue>(
  props: Omit<React.ComponentProps<typeof TableColumnGroupMenu>, "column">,
) {
  const { column } = useColumnHeaderContext<TData, TValue>(true)
  return <TableColumnGroupMenu column={column} {...props} />
}

DataTableColumnGroupMenu.displayName = "DataTableColumnGroupMenu"

"use client"

/**
 * Niko Table's tooltip primitive, React Aria build. Radix-shaped API
 * (`TooltipProvider`, `Tooltip`, `TooltipTrigger asChild`, `TooltipContent
 * side`) on top of `react-aria-components` `TooltipTrigger` / `Focusable` and the
 * React Aria shadcn `Tooltip` popup.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import {
  Focusable,
  TooltipTrigger as TooltipTriggerPrimitive,
  type Placement,
} from "react-aria-components"

import { Tooltip as TooltipPopup } from "@/components/ui/tooltip"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"
type FocusableChild = React.ComponentProps<typeof Focusable>["children"]

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

// React Aria has no provider: the delay is read per tooltip from here.
const TooltipDelayContext = React.createContext(0)

function TooltipProvider({
  delayDuration,
  delay,
  children,
}: {
  /** Radix name. */
  delayDuration?: number
  /** Base UI name; accepted so a spread of both typechecks. */
  delay?: number
  children?: React.ReactNode
}) {
  return (
    <TooltipDelayContext.Provider value={delayDuration ?? delay ?? 0}>
      {children}
    </TooltipDelayContext.Provider>
  )
}

function Tooltip({
  open,
  defaultOpen,
  onOpenChange,
  delayDuration,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  delayDuration?: number
  children?: React.ReactNode
}) {
  const delay = React.useContext(TooltipDelayContext)
  return (
    <TooltipTriggerPrimitive
      delay={delayDuration ?? delay}
      closeDelay={0}
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </TooltipTriggerPrimitive>
  )
}

function TooltipTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const child =
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children) ? (
      // Slot: the trigger's own props (refs, handlers, classes) merge onto the child.
      React.cloneElement(
        children,
        mergeProps(children.props, props) as React.HTMLAttributes<HTMLElement>,
      )
    ) : (
      <button type="button" {...props}>
        {children}
      </button>
    )
  // Focusable types its child as a host element; ours forward ref + props.
  return <Focusable>{child as FocusableChild}</Focusable>
}

function TooltipContent({
  side = "top",
  align = "center",
  sideOffset = 4,
  alignOffset = 0,
  className,
  children,
}: {
  side?: Side
  align?: Align
  sideOffset?: number
  alignOffset?: number
  className?: string
  children?: React.ReactNode
}) {
  return (
    <TooltipPopup
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
    >
      {children}
    </TooltipPopup>
  )
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger }

"use client"

/**
 * Niko Table's dropdown-menu primitive, React Aria build. Radix-shaped API
 * (`DropdownMenuTrigger asChild`, `DropdownMenuContent align side`, items with
 * `onClick` / `disabled` / `variant`, submenus, radio groups) on top of
 * `react-aria-components` `MenuTrigger` / `Pressable` and the React Aria shadcn
 * dropdown-menu pieces (a React Aria `Menu` in a `Popover`).
 *
 * A React Aria menu is a collection: only items, labels, separators, groups
 * and submenus render inside it. Wrap any other content in
 * `DropdownMenuPanel`, which renders it as a non-focusable menu node.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import {
  Header,
  MenuTrigger,
  OverlayTriggerStateContext,
  Pressable,
  type Placement,
  type PressEvent,
} from "react-aria-components"

import {
  DropdownMenu as MenuPopover,
  DropdownMenuGroup,
  DropdownMenuItem as MenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent as SubmenuPopover,
  DropdownMenuSubTrigger as SubmenuItem,
} from "@/components/ui/dropdown-menu"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"
type PressableChild = React.ComponentProps<typeof Pressable>["children"]

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

/** Plain text of a node tree, for React Aria's type-to-select. */
function textOf(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(textOf).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(node))
    return textOf(node.props.children)
  return ""
}

function DropdownMenu({
  open,
  defaultOpen,
  onOpenChange,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Radix option; React Aria menus are always modal. */
  modal?: boolean
  children?: React.ReactNode
}) {
  return (
    <MenuTrigger
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </MenuTrigger>
  )
}

function DropdownMenuTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  // MenuTrigger hands its press, keyboard and aria props to the Pressable.
  const isOpen = React.useContext(OverlayTriggerStateContext)?.isOpen ?? false
  const state = { "data-state": isOpen ? "open" : "closed" }
  const child =
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children) ? (
      // Slot: the trigger's own props (refs, handlers, classes) merge onto the child.
      React.cloneElement(
        children,
        mergeProps(
          children.props,
          props,
          state,
        ) as React.HTMLAttributes<HTMLElement>,
      )
    ) : (
      <button type="button" {...props} {...state}>
        {children}
      </button>
    )
  return <Pressable>{child as PressableChild}</Pressable>
}

function DropdownMenuContent({
  align = "center",
  side = "bottom",
  sideOffset = 4,
  alignOffset = 0,
  className,
  children,
}: {
  align?: Align
  side?: Side
  sideOffset?: number
  alignOffset?: number
  className?: string
  children?: React.ReactNode
}) {
  return (
    <MenuPopover
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
    >
      {children}
    </MenuPopover>
  )
}

interface DropdownMenuItemProps {
  /** Runs on pointer and keyboard activation; the press event carries `shiftKey`. */
  onClick?: (event: PressEvent) => void
  disabled?: boolean
  variant?: "default" | "destructive"
  inset?: boolean
  textValue?: string
  className?: string
  children?: React.ReactNode
}

function DropdownMenuItem({
  onClick,
  disabled,
  textValue,
  children,
  ...props
}: DropdownMenuItemProps) {
  return (
    <MenuItem
      {...props}
      onPress={onClick}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </MenuItem>
  )
}

function DropdownMenuSubTrigger({
  disabled,
  textValue,
  children,
  ...props
}: Omit<DropdownMenuItemProps, "onClick" | "variant">) {
  return (
    <SubmenuItem
      {...props}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </SubmenuItem>
  )
}

function DropdownMenuSubContent({
  sideOffset,
  alignOffset,
  className,
  children,
}: {
  className?: string
  children?: React.ReactNode
  sideOffset?: number
  alignOffset?: number
}) {
  return (
    <SubmenuPopover
      // Unset keeps the shadcn aria submenu defaults.
      {...(sideOffset === undefined ? {} : { offset: sideOffset })}
      {...(alignOffset === undefined ? {} : { crossOffset: alignOffset })}
      className={className}
    >
      {children}
    </SubmenuPopover>
  )
}

function DropdownMenuRadioGroup({
  value,
  onValueChange,
  children,
}: {
  value?: string
  onValueChange?: (value: string) => void
  children?: React.ReactNode
}) {
  return (
    <DropdownMenuGroup
      selectionMode="single"
      disallowEmptySelection
      selectedKeys={value === undefined ? [] : [value]}
      onSelectionChange={keys => {
        if (keys === "all") return
        const [key] = keys
        if (key !== undefined) onValueChange?.(String(key))
      }}
    >
      {children}
    </DropdownMenuGroup>
  )
}

function DropdownMenuRadioItem({
  value,
  disabled,
  textValue,
  children,
  ...props
}: Omit<DropdownMenuItemProps, "onClick" | "variant"> & { value: string }) {
  return (
    <MenuItem
      {...props}
      id={value}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </MenuItem>
  )
}

function stopMenuKeys(event: React.KeyboardEvent) {
  // Keep typing / arrows inside the panel's own controls; Escape still closes.
  if (event.key !== "Escape") event.stopPropagation()
}

function DropdownMenuPanel({ children }: { children: React.ReactNode }) {
  return (
    <Header
      role="presentation"
      onKeyDown={stopMenuKeys}
      onKeyUp={stopMenuKeys}
      // The menu moves focus to its first item when focus enters it.
      onFocus={event => event.stopPropagation()}
    >
      {children}
    </Header>
  )
}

export {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuPanel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
}

"use client"

/**
 * Niko Table's button primitive, React Aria build. Same API as the shadcn
 * Radix `Button` (native `<button>` props, `variant`, `size`, `asChild`), styled
 * with the React Aria shadcn `buttonVariants`. A native button (not the React
 * Aria `Button`) keeps `onClick` / `disabled` / `type` / `ref` working at every
 * Niko Table call site, and lets the overlay triggers wrap it in `Pressable`.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { VariantProps } from "class-variance-authority"

import { buttonVariants } from "@/components/ui/button"
import { cn } from "@/lib/utils"

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const classes = cn(buttonVariants({ variant, size }), className)

  if (
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)
  ) {
    // Slot: the child element is the button (e.g. a link styled as one); its
    // own handlers and refs compose with the button's.
    return React.cloneElement(children, {
      ...mergeProps(children.props, { "data-slot": "button" }, props),
      className: cn(classes, children.props.className),
    } as React.HTMLAttributes<HTMLElement>)
  }

  return (
    <button
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={classes}
      {...props}
    >
      {children}
    </button>
  )
}

export { Button }
